1	import React, { useState, useCallback, useEffect, useMemo } from "react";
2	import { useSearchParams, useLocation, useNavigate } from "react-router-dom";
3	import { useQuery, useQueryClient } from "@tanstack/react-query";
4	import { useAuth } from "@/hooks/useAuth";
5	import { supabase } from "@/integrations/supabase/client";
6	import AppHeader from "@/components/AppHeader";
7	import AuthDialog from "@/components/AuthDialog";
8	import JobSidebar from "@/components/JobSidebar";
9	import JobDetailView from "@/components/JobDetailView";
10	import JobsOverviewCard from "@/components/JobsOverviewCard";
11	import { SidebarProvider, SidebarTrigger, SidebarInset } from "@/components/ui/sidebar";
12	import { Card, CardContent } from "@/components/ui/card";
13	import { Badge } from "@/components/ui/badge";
14	import { Button } from "@/components/ui/button";
15	import { Plus, Briefcase, FileText, Coins, CheckCircle2, ChevronRight, ChevronLeft } from "lucide-react";
16	import { format } from "date-fns";
17	import { toast } from "sonner";
18	import OnboardingWizard from "@/components/OnboardingWizard";
19	
20	export interface PastJob {
21	  id: string;
22	  title: string | null;
23	  job_description: string;
24	  status: string;
25	  created_at: string;
26	  resume_count: number;
27	  jd_analysis_json: any;
28	  dynamic_weights_json: Record<string, number> | null;
29	  inbox_email: string | null;
30	}
31	
32	export interface Result {
33	  id: string;
34	  resume_id: string;
35	  overall_score: number;
36	  missing_skills: string[];
37	  summary: string | null;
38	  interview_questions: any;
39	  filename: string;
40	  file_path: string | null;
41	  candidate_name: string | null;
42	  candidate_email?: string | null;
43	  candidate_phone?: string | null;
44	  candidate_location?: string | null;
45	  // Dynamic scoring fields
46	  hard_fit?: boolean;
47	  category_scores_json?: Record<string, { score: number; evidence?: any[]; notes?: string }>;
48	  confidence?: number;
49	  strengths_json?: string[];
50	  gaps_json?: string[];
51	  explanation_json?: { summary?: string; why_ranked_here?: string; key_tradeoffs?: string; matched_preferred?: string[]; missing_preferred?: string[] };
52	  matched_must_haves?: string[];
53	  missing_must_haves?: string[];
54	  scoring_version?: string;
55	  pending?: boolean;
56	  parsed_json?: any;
57	  assigned_to?: string | null;
58	  source?: string | null;
59	}
60	
61	export interface ExistingResume {
62	  id: string;
63	  filename: string;
64	  file_path: string | null;
65	  candidate_name: string | null;
66	  created_at: string;
67	  source?: string | null;
68	}
69	
70	type ViewMode = "dashboard" | "my-jobs" | "job-detail" | "new-job";
71	
72	const ONBOARDING_KEY = "rankora_onboarding_done";
73	
74	const Index = () => {
75	  const { user, profile } = useAuth();
76	  const [searchParams, setSearchParams] = useSearchParams();
77	  const location = useLocation();
78	  const navigate = useNavigate();
79	
80	  // Show onboarding wizard for first-time users
81	  const [showOnboarding, setShowOnboarding] = useState(() => {
82	    if (typeof window === "undefined") return false;
83	    return !localStorage.getItem(ONBOARDING_KEY);
84	  });
85	
86	  const completeOnboarding = useCallback(() => {
87	    localStorage.setItem(ONBOARDING_KEY, "1");
88	    setShowOnboarding(false);
89	  }, []);
90	
91	  const queryClient = useQueryClient();
92	
93	  const { data: pastJobs = [], isLoading: loadingPastJobs } = useQuery({
94	    queryKey: ["pastJobs", user?.id],
95	    queryFn: async () => {
96	      const { data: jobs } = await supabase
97	        .from("jobs")
98	        .select("id, title, job_description, status, created_at, jd_analysis_json, dynamic_weights_json, inbox_email, resumes(count)")
99	        .eq("user_id", user!.id)
100	        .order("created_at", { ascending: false })
101	        .limit(50);
102	      if (!jobs) return [];
103	      return jobs.map((j: any) => ({
104	        id: j.id,
105	        title: j.title,
106	        job_description: j.job_description,
107	        status: j.status,
108	        created_at: j.created_at,
109	        resume_count: j.resumes?.[0]?.count ?? 0,
110	        jd_analysis_json: j.jd_analysis_json,
111	        dynamic_weights_json: j.dynamic_weights_json,
112	        inbox_email: j.inbox_email ?? null,
113	      })) as PastJob[];
114	    },
115	    enabled: !!user,
116	    staleTime: 2 * 60 * 1000,
117	  });
118	
119	  const [selectedJobId, setSelectedJobId] = useState<string | null>(null);
120	  const [view, setView] = useState<ViewMode>(location.pathname === "/jobs" ? "my-jobs" : "dashboard");
121	  const [results, setResults] = useState<Result[]>([]);
122	  const [existingResumes, setExistingResumes] = useState<ExistingResume[]>([]);
123	  const [authOpen, setAuthOpen] = useState(false);
124	
125	  const selectedJob = useMemo(() => pastJobs.find((j) => j.id === selectedJobId) ?? null, [pastJobs, selectedJobId]);
126	
127	  // Sync view with route path
128	  useEffect(() => {
129	    if (location.pathname === "/jobs") {
130	      setView("my-jobs");
131	      setSelectedJobId(null);
132	    }
133	  }, [location.pathname]);
134	
135	  // Handle URL params for deep linking
136	  useEffect(() => {
137	    const jobParam = searchParams.get("job");
138	    const newParam = searchParams.get("new");
139	
140	    if (jobParam && user) {
141	      loadJobData(jobParam);
142	      setSearchParams({}, { replace: true });
143	    } else if (newParam && user) {
144	      handleNewJob();
145	      setSearchParams({}, { replace: true });
146	    }
147	    // eslint-disable-next-line react-hooks/exhaustive-deps
148	  }, [searchParams, user]);
149	
150	  const loadJobData = async (jobId: string) => {
151	    setSelectedJobId(jobId);
152	    setView("job-detail");
153	    try {
154	      // Single query for all resume data (was 2 separate queries)
155	      const { data: allResumes } = await supabase
156	        .from("resumes")
157	        .select("id, filename, file_path, candidate_name, created_at, parsed_json, source")
158	        .eq("job_id", jobId)
159	        .order("created_at", { ascending: false });
160	
161	      const resumeData = allResumes ?? [];
162	      setExistingResumes(resumeData.map((r) => ({
163	        id: r.id, filename: r.filename, file_path: r.file_path,
164	        candidate_name: r.candidate_name, created_at: r.created_at,
165	        source: (r as { source?: string | null }).source ?? null,
166	      })));
167	
168	      if (resumeData.length === 0) {
169	        setResults([]);
170	        return;
171	      }
172	
173	      const resumeIds = resumeData.map((r) => r.id);
174	      const { data: resultData } = await supabase
175	        .from("results")
176	        .select("id, resume_id, overall_score, missing_skills, summary, interview_questions, hard_fit, category_scores_json, confidence, strengths_json, gaps_json, explanation_json, matched_must_haves, missing_must_haves, scoring_version")
177	        .in("resume_id", resumeIds);
178	
179	      const resumeMap = new Map(resumeData.map((r) => [r.id, r]));
180	      const allMerged: Result[] = (resultData ?? []).map((r: any) => {
181	        const resume = resumeMap.get(r.resume_id);
182	        const parsed = resume?.parsed_json as any;
183	        return {
184	          ...r,
185	          overall_score: r.overall_score ?? 0,
186	          missing_skills: r.missing_skills ?? [],
187	          filename: resume?.filename ?? "Unknown",
188	          file_path: resume?.file_path ?? null,
189	          candidate_name: resume?.candidate_name ?? null,
190	          candidate_email: parsed?.email ?? parsed?.contact?.email ?? null,
191	          candidate_phone: parsed?.phone ?? parsed?.contact?.phone ?? null,
192	          candidate_location: parsed?.location ?? parsed?.contact?.location ?? null,
193	          parsed_json: resume?.parsed_json ?? null,
194	          source: (resume as { source?: string | null })?.source ?? null,
195	        };
196	      });
197	      // Deduplicate by resume_id — keep highest scoring result per resume
198	      const deduped = new Map<string, Result>();
199	      for (const r of allMerged) {
200	        const existing = deduped.get(r.resume_id);
201	        if (!existing || r.overall_score > existing.overall_score) {
202	          deduped.set(r.resume_id, r);
203	        }
204	      }
205	      const merged = Array.from(deduped.values());
206	      merged.sort((a, b) => b.overall_score - a.overall_score);
207	      setResults(merged);
208	    } catch (err) {
209	      toast.error("Failed to load job data");
210	    }
211	  };
212	
213	  const handleNewJob = () => {
214	    setSelectedJobId(null);
215	    setView("new-job");
216	    setResults([]);
217	    setExistingResumes([]);
218	  };
219	
220	  const handleGoToDashboard = () => {
221	    setSelectedJobId(null);
222	    setView("dashboard");
223	    setResults([]);
224	    setExistingResumes([]);
225	    navigate("/", { replace: true });
226	  };
227	
228	  const handleGoToMyJobs = () => {
229	    setSelectedJobId(null);
230	    setView("my-jobs");
231	    setResults([]);
232	    setExistingResumes([]);
233	    navigate("/jobs", { replace: true });
234	  };
235	
236	  const handleJobCreated = (job: PastJob) => {
237	    queryClient.setQueryData<PastJob[]>(["pastJobs", user?.id], (prev) => [job, ...(prev ?? [])]);
238	    setSelectedJobId(job.id);
239	    loadJobData(job.id);
240	  };
241	
242	  const handleJobUpdated = (jobId: string, updates: Partial<PastJob>) => {
243	    queryClient.setQueryData<PastJob[]>(["pastJobs", user?.id], (prev) =>
244	      (prev ?? []).map((j) => (j.id === jobId ? { ...j, ...updates } : j))
245	    );
246	  };
247	
248	  const handleDeleteJobs = async (jobIds: string[]) => {
249	    try {
250	      const { error } = await supabase.from("jobs").delete().in("id", jobIds);
251	      if (error) throw error;
252	      queryClient.setQueryData<PastJob[]>(["pastJobs", user?.id], (prev) =>
253	        (prev ?? []).filter((j) => !jobIds.includes(j.id))
254	      );
255	    } catch (err: any) {
256	      toast.error(err?.message || "Failed to delete jobs");
257	    }
258	  };
259	
260	  const requireAuth = useCallback(() => {
261	    if (!user) { setAuthOpen(true); return true; }
262	    return false;
263	  }, [user]);
264	
265	  return (
266	    <SidebarProvider className="h-svh overflow-hidden">
267	      <JobSidebar
268	        showDashboard={view === "dashboard"}
269	        showMyJobs={view === "my-jobs" || view === "job-detail"}
270	        onNewJob={handleNewJob}
271	        onDashboard={handleGoToDashboard}
272	        onMyJobs={handleGoToMyJobs}
273	        onAuthRequired={() => setAuthOpen(true)}
274	        isAuthenticated={!!user}
275	      />
276	
277	      <SidebarInset className="h-svh overflow-hidden bg-sidebar p-2 pl-0">
278	        <div className="h-full flex flex-col rounded-xl border bg-background overflow-hidden">
279	        <AppHeader />
280	        <div className="flex items-center h-10 px-4 md:hidden">
281	          <SidebarTrigger />
282	          <span className="ml-2 text-sm font-medium text-muted-foreground">Menu</span>
283	        </div>
284	        <div className="flex-1 overflow-y-auto">
285	
286	        {/* Dashboard view */}
287	        {view === "dashboard" && user ? (
288	          <main className="w-full px-6 sm:px-8 lg:px-10 py-8 space-y-6">
289	            {/* Hero Section — Greeting + Create Button */}
290	            <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
291	              <div>
292	                <h1 className="text-2xl font-bold text-foreground">
293	                  Welcome back, {user.user_metadata?.full_name?.split(" ")[0] || user.email?.split("@")[0]}!
294	                </h1>
295	                <p className="text-sm text-muted-foreground mt-1">
296	                  Here's an overview of your hiring activity and insights.
297	                </p>
298	              </div>
299	              <Button className="gap-2" onClick={handleNewJob}>
300	                <Plus className="h-4 w-4" /> Create Job
301	              </Button>
302	            </div>
303	
304	            {/* Stats Cards */}
305	            <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
306	              {[
307	                { label: "Total Jobs", value: pastJobs.length, icon: Briefcase, color: "bg-blue-100 text-blue-600" },
308	                { label: "Total Resumes", value: pastJobs.reduce((s, j) => s + j.resume_count, 0), icon: FileText, color: "bg-emerald-100 text-emerald-600" },
309	                { label: "Credits Left", value: (() => { const p = profile; if (!p) return 0; const s = (p.subscription_credits ?? 0) + (p.topup_credits ?? 0) + (p.bonus_credits ?? 0); return s > 0 ? s : (p.credits ?? 0); })(), icon: Coins, color: "bg-amber-100 text-amber-600" },
310	                { label: "Jobs Completed", value: pastJobs.filter(j => j.status === "completed").length, icon: CheckCircle2, color: "bg-violet-100 text-violet-600" },
311	              ].map((s) => (
312	                <Card key={s.label} className="border border-border/60 shadow-sm hover:shadow-md transition-shadow">
313	                  <CardContent className="px-5 py-4 flex items-center gap-4">
314	                    <div className={`h-11 w-11 rounded-xl flex items-center justify-center shrink-0 ${s.color}`}>
315	                      <s.icon className="h-5 w-5" />
316	                    </div>
317	                    <div>
318	                      <p className="text-2xl font-bold tabular-nums text-foreground">{s.value}</p>
319	                      <p className="text-xs text-muted-foreground font-medium">{s.label}</p>
320	                    </div>
321	                  </CardContent>
322	                </Card>
323	              ))}
324	            </div>
325	
326	            {/* Recent Jobs */}
327	            {pastJobs.length > 0 && (
328	              <div className="space-y-3">
329	                <div className="flex items-center justify-between">
330	                  <h2 className="text-sm font-semibold text-foreground">Recent Jobs</h2>
331	                  <button onClick={handleGoToMyJobs} className="text-xs font-medium text-primary hover:text-primary/80 transition-colors">
332	                    View All Jobs →
333	                  </button>
334	                </div>
335	                <div className="grid gap-3">
336	                  {pastJobs.slice(0, 5).map((job) => (
337	                    <Card key={job.id} className="cursor-pointer hover:shadow-md transition-all border border-border/60" onClick={() => loadJobData(job.id)}>
338	                      <CardContent className="px-5 py-3.5 flex items-center justify-between">
339	                        <div className="flex items-center gap-3 min-w-0">
340	                          <div className="h-9 w-9 rounded-lg bg-primary/10 flex items-center justify-center shrink-0">
341	                            <Briefcase className="h-4 w-4 text-primary" />
342	                          </div>
343	                          <div className="min-w-0">
344	                            <p className="text-sm font-medium text-foreground truncate">{job.title || "Untitled Job"}</p>
345	                            <p className="text-xs text-muted-foreground mt-0.5">
346	                              {job.resume_count} resume{job.resume_count !== 1 ? "s" : ""} · {format(new Date(job.created_at), "MMM d, yyyy")}
347	                            </p>
348	                          </div>
349	                        </div>
350	                        <div className="flex items-center gap-3 shrink-0">
351	                          <Badge
352	                            variant={job.status === "completed" ? "success" : job.status === "pending" || job.status === "processing" ? "warning" : "outline"}
353	                            className="text-xs"
354	                          >
355	                            {job.status.charAt(0).toUpperCase() + job.status.slice(1)}
356	                          </Badge>
357	                          <ChevronRight className="h-4 w-4 text-muted-foreground" />
358	                        </div>
359	                      </CardContent>
360	                    </Card>
361	                  ))}
362	                </div>
363	              </div>
364	            )}
365	
366	            {/* Getting started guide — show only for new users */}
367	            {pastJobs.length === 0 && !loadingPastJobs && (
368	              <Card className="border border-border/60 shadow-sm">
369	                <CardContent className="px-5 py-4 space-y-3">
370	                  <h2 className="text-sm font-medium text-foreground">Getting Started</h2>
371	                  <div className="space-y-2.5">
372	                    {[
373	                      { step: "1", text: "Click \"Create New Job\" and paste a job description" },
374	                      { step: "2", text: "Upload candidate resumes (PDF, DOCX, or forward via email)" },
375	                      { step: "3", text: "AI ranks all candidates with scores, strengths, and gaps" },
376	                    ].map((item) => (
377	                      <div key={item.step} className="flex items-start gap-3 text-sm">
378	                        <span className="h-5 w-5 rounded-full bg-primary text-primary-foreground text-xs font-bold flex items-center justify-center shrink-0 mt-0.5">{item.step}</span>
379	                        <span className="text-muted-foreground">{item.text}</span>
380	                      </div>
381	                    ))}
382	                  </div>
383	                </CardContent>
384	              </Card>
385	            )}
386	          </main>
387	        ) : view === "my-jobs" && user ? (
388	          /* My Jobs view — full management */
389	          <main className="w-full px-6 sm:px-8 lg:px-10 py-8 space-y-6">
390	            <div className="flex flex-col sm:flex-row sm:items-start sm:justify-between gap-4">
391	              <div className="space-y-1">
392	                <h1 className="text-2xl font-bold text-foreground">My Jobs</h1>
393	                <p className="text-sm text-muted-foreground">Manage all your job postings.</p>
394	              </div>
395	              <Button className="gap-2 shrink-0" onClick={handleNewJob}>
396	                <Plus className="h-4 w-4" /> Create Job
397	              </Button>
398	            </div>
399	            <JobsOverviewCard jobs={pastJobs} loading={loadingPastJobs} onSelectJob={loadJobData} onDeleteJobs={handleDeleteJobs} />
400	          </main>
401	        ) : (
402	          <JobDetailView
403	            selectedJobId={selectedJobId}
404	            selectedJob={selectedJob}
405	            results={results}
406	            setResults={setResults}
407	            existingResumes={existingResumes}
408	            setExistingResumes={setExistingResumes}
409	            onJobCreated={handleJobCreated}
410	            onAuthRequired={() => setAuthOpen(true)}
411	            isAuthenticated={!!user}
412	            pastJobs={pastJobs}
413	            onJobUpdated={handleJobUpdated}
414	            onBack={handleGoToMyJobs}
415	          />
416	        )}
417	        </div>
418	        </div>
419	      </SidebarInset>
420	
421	      <AuthDialog open={authOpen} onOpenChange={setAuthOpen} defaultTab="signin" />
422	
423	      {user && showOnboarding && (
424	        <OnboardingWizard
425	          open={showOnboarding}
426	          onComplete={completeOnboarding}
427	          onCreateJob={() => { completeOnboarding(); handleNewJob(); }}
428	          onGoToTeam={() => { completeOnboarding(); navigate("/team"); }}
429	          userName={user.user_metadata?.full_name?.split(" ")[0] || user.email?.split("@")[0] || "there"}
430	        />
431	      )}
432	    </SidebarProvider>
433	  );
434	};
435	
436	export default Index;
