77	// ─── Helpers ──────────────────────────────────────────────────────────────────
78	
79	function fmtDate(d: string | null) {
80	  if (!d) return "—";
81	  try {
82	    return format(parseISO(d), "MMM d, yyyy");
83	  } catch {
84	    return "—";
85	  }
86	}
87	
88	function fmtDateTime(d: string | null) {
89	  if (!d) return "—";
90	  try {
91	    return format(parseISO(d), "MMM d, yyyy · h:mm a");
92	  } catch {
93	    return "—";
94	  }
95	}
96	
97	function fmtCurrency(amount: number | null, currency = "USD") {
98	  if (amount == null) return "—";
99	  return new Intl.NumberFormat("en-US", {
100	    style: "currency",
101	    currency,
102	    maximumFractionDigits: 0,
103	  }).format(amount);
104	}
105	
106	// ─── DeadlineBadge ────────────────────────────────────────────────────────────
107	
108	function DeadlineBadge({ deadline }: { deadline: string | null }) {
109	  if (!deadline) return <span className="text-muted-foreground text-xs">—</span>;
110	  try {
111	    const days = differenceInDays(parseISO(deadline), new Date());
112	    if (days < 0) {
113	      return (
114	        <span className="inline-flex items-center gap-1 text-[11px] font-medium text-red-600 dark:text-red-400">
