173	        </div>
174	        <div className="h-1.5 w-full rounded-full bg-muted overflow-hidden">
175	          <div className={`h-full rounded-full transition-all ${color}`} style={{ width: `${pct}%` }} />
176	        </div>
177	      </div>
178	    );
179	  } catch {
180	    return <span className="text-muted-foreground text-xs">—</span>;
