87	function normalizeSkill(skill: string): string {
88	  // Preserve meaningful symbols: C#, C++, .NET, etc.
89	  const lower = skill.toLowerCase().trim()
90	    .replace(/\s+/g, ' ')
91	    .replace(/[\/\-]/g, ''); // Only strip slashes and hyphens, NOT dots, #, or +
92	  return synonymToCanonical.get(lower) || synonymToCanonical.get(skill.toLowerCase().trim()) || lower;
93	}
