99	function tokenOverlap(a: string, b: string): number {
100	  const tokensA = tokenize(a);
101	  const tokensB = tokenize(b);
102	  if (tokensA.length === 0 || tokensB.length === 0) return 0;
103	  const setB = new Set(tokensB);
104	  const matched = tokensA.filter(t => setB.has(t)).length;
105	  return matched / Math.max(tokensA.length, tokensB.length);
106	}
