108	function fuzzyMatch(jdTerm: string, resumeTerms: string[]): boolean {
109	  const normalizedJd = normalizeSkill(jdTerm);
110	  for (const rt of resumeTerms) {
111	    const normalizedResume = normalizeSkill(rt);
112	    if (normalizedJd === normalizedResume) return true;
113	    if (normalizedJd.includes(normalizedResume) || normalizedResume.includes(normalizedJd)) return true;
114	    if (tokenOverlap(normalizedJd, normalizedResume) >= 0.5) return true;
115	  }
116	  return false;
117	}
