34	/** Send an SMS via Twilio REST API */
35	async function sendViaTwilio(
36	  accountSid: string,
37	  authToken: string,
38	  fromNumber: string,
39	  toPhone: string,
40	  body: string
41	): Promise<{ ok: boolean; sid?: string; errorMessage?: string }> {
42	  const url = `https://api.twilio.com/2010-04-01/Accounts/${accountSid}/Messages.json`;
43	
44	  const params = new URLSearchParams();
45	  params.append("To", toPhone);
46	  params.append("From", fromNumber);
47	  params.append("Body", body);
48	
49	  const credentials = btoa(`${accountSid}:${authToken}`);
50	
51	  const res = await fetch(url, {
52	    method: "POST",
53	    headers: {
54	      "Authorization": `Basic ${credentials}`,
55	      "Content-Type": "application/x-www-form-urlencoded",
56	    },
57	    body: params.toString(),
58	  });
59	
60	  const json = (await res.json()) as TwilioMessageResponse;
61	
62	  if (!res.ok) {
63	    return {
64	      ok: false,
65	      errorMessage: json.error_message || `Twilio error (status ${res.status}, code ${json.error_code})`,
66	    };
67	  }
68	
69	  return { ok: true, sid: json.sid };
70	}
